{
  "steps": [
    {
      "action": "Inventory the target binary and analysis prerequisites, recording format, architecture, entrypoints, sections, imports, exports, symbols, strings, protections, and any analysis blockers relevant to locating the virtualized input-validation logic.",
      "technique": "RE-BINARY-INVENTORY",
      "deterministic_check": [
        "The analyzed artifact hash matches campaign metadata.",
        "Binary format and architecture are recorded.",
        "Expected inventory artifacts exist and parse successfully.",
        "Missing or malformed inputs are reported as incomplete rather than absence."
      ]
    },
    {
      "action": "Map the static call relationships around the input surface, identifying entrypoints, callers, callees, indirect-call uncertainty, and helpers that reach the virtualized validation routine.",
      "technique": "RE-STATIC-CALLGRAPH",
      "deterministic_check": [
        "Every claimed call edge has an address or symbol locator.",
        "Unresolved indirect calls are listed explicitly.",
        "The call graph identifies which paths are proven and which remain candidates."
      ]
    },
    {
      "action": "Trace input acquisition through parsing, transformations, comparisons, branch decisions, success paths, and rejection paths in the virtualized validation logic, then solve the input that satisfies every accepted branch.",
      "technique": "RE-INPUT-VALIDATION-TRACE",
      "deterministic_check": [
        "The input source and destination representation are identified.",
        "Every success and rejection branch has a code locator.",
        "Transformations and comparison constants are supported by decompilation or disassembly evidence.",
        "Unknown helper behavior is represented as an unresolved dependency.",
        "The solved input is supported by recorded branch constraints and constants."
      ]
    },
    {
      "action": "Confirm the solved input with a bounded, network-isolated local replay using an authorized debugger or instrumentation probe, with explicit readiness, trigger, timeout, and hit requirements.",
      "technique": "RE-BOUNDED-RUNTIME-CONFIRMATION",
      "deterministic_check": [
        "Runtime execution is authorized by campaign scope.",
        "The sensor or breakpoint is proven ready before interpreting hits or zero hits.",
        "The trigger window and timeout are bounded and recorded.",
        "Network isolation is verified and recorded before replay.",
        "Runtime identity is correlated to the same binary hash and module as static evidence.",
        "The replay reaches the validation success path and does not contact the network."
      ]
    }
  ]
}
